test "riscv vs llvm-mc: RV32C (45 cases)" {
    @setEvalBranchQuota(100_000);
    var cb = CodeBuffer.init(std.testing.allocator);
    defer cb.deinit();
    const a = rv.Assembler32.init(&cb);
    var fails: u32 = 0;
    try a.cNop();
    fails += tail(&cb, &.{ 0x01, 0x00 }, "c.nop");
    try a.cAddi(.a0, 1);
    fails += tail(&cb, &.{ 0x05, 0x05 }, "c.addi a0, 1");
    try a.cAddi(.sp, -32);
    fails += tail(&cb, &.{ 0x01, 0x11 }, "c.addi sp, -32");
    try a.cLi(.t6, -32);
    fails += tail(&cb, &.{ 0x81, 0x5f }, "c.li t6, -32");
    try a.cLi(.a0, 31);
    fails += tail(&cb, &.{ 0x7d, 0x45 }, "c.li a0, 31");
    try a.cLui(.a0, 1);
    fails += tail(&cb, &.{ 0x05, 0x65 }, "c.lui a0, 1");
    try a.cLui(.t6, -1);
    fails += tail(&cb, &.{ 0xfd, 0x7f }, "c.lui t6, 0xfffff");
    try a.cMv(.a0, .t6);
    fails += tail(&cb, &.{ 0x7e, 0x85 }, "c.mv a0, t6");
    try a.cAdd(.ra, .s11);
    fails += tail(&cb, &.{ 0xee, 0x90 }, "c.add ra, s11");
    try a.cJr(.t0);
    fails += tail(&cb, &.{ 0x82, 0x82 }, "c.jr t0");
    try a.cJalr(.a0);
    fails += tail(&cb, &.{ 0x02, 0x95 }, "c.jalr a0");
    try a.cRet();
    fails += tail(&cb, &.{ 0x82, 0x80 }, "c.jr ra");
    try a.cEbreak();
    fails += tail(&cb, &.{ 0x02, 0x90 }, "c.ebreak");
    try a.cLwsp(.ra, 252);
    fails += tail(&cb, &.{ 0xfe, 0x50 }, "c.lwsp ra, 252(sp)");
    try a.cSwsp(.t6, 252);
    fails += tail(&cb, &.{ 0xfe, 0xdf }, "c.swsp t6, 252(sp)");
    try a.cLwsp(.a0, 0);
    fails += tail(&cb, &.{ 0x02, 0x45 }, "c.lwsp a0, 0(sp)");
    try a.cAddi16sp(-512);
    fails += tail(&cb, &.{ 0x01, 0x71 }, "c.addi16sp sp, -512");
    try a.cAddi16sp(496);
    fails += tail(&cb, &.{ 0x7d, 0x61 }, "c.addi16sp sp, 496");
    try a.cAddi16sp(16);
    fails += tail(&cb, &.{ 0x41, 0x61 }, "c.addi16sp sp, 16");
    try a.cAddi4spn(.s0, 4);
    fails += tail(&cb, &.{ 0x40, 0x00 }, "c.addi4spn s0, sp, 4");
    try a.cAddi4spn(.a5, 1020);
    fails += tail(&cb, &.{ 0xfc, 0x1f }, "c.addi4spn a5, sp, 1020");
    try a.cLw(.a0, 124, .s1);
    fails += tail(&cb, &.{ 0xe8, 0x5c }, "c.lw a0, 124(s1)");
    try a.cSw(.s0, 4, .a5);
    fails += tail(&cb, &.{ 0xc0, 0xc3 }, "c.sw s0, 4(a5)");
    try a.cSrli(.a0, 1);
    fails += tail(&cb, &.{ 0x05, 0x81 }, "c.srli a0, 1");
    try a.cSrai(.s1, 31);
    fails += tail(&cb, &.{ 0xfd, 0x84 }, "c.srai s1, 31");
    try a.cAndi(.a3, -32);
    fails += tail(&cb, &.{ 0x81, 0x9a }, "c.andi a3, -32");
    try a.cSub(.a0, .a1);
    fails += tail(&cb, &.{ 0x0d, 0x8d }, "c.sub a0, a1");
    try a.cXor(.s0, .a5);
    fails += tail(&cb, &.{ 0x3d, 0x8c }, "c.xor s0, a5");
    try a.cOr(.a5, .s0);
    fails += tail(&cb, &.{ 0xc1, 0x8f }, "c.or a5, s0");
    try a.cAnd(.s1, .s1);
    fails += tail(&cb, &.{ 0xe5, 0x8c }, "c.and s1, s1");
    try a.cSlli(.t6, 31);
